// Embeds the default colors in lib/src/colors.g.dart.
// Run from the package root: dart run tool/gen_colors.dart
import 'dart:io';

void main() {
  final source = File('config/color.json5').readAsStringSync();
  if (source.contains("'''")) {
    throw StateError("color.json5 contains ''', which breaks embedding");
  }
  File('lib/src/colors.g.dart').writeAsStringSync('''
// Generated by tool/gen_colors.dart. Do not edit.
// Source: config/color.json5

const defaultColors = r\'\'\'
$source\'\'\';
''');
}
